export const ARYAMAN_BRAND_FA = 'اتوماسیون آریامن';
export const ARYAMAN_LOGO_DATA_URI = 'data:image/png;base64,';

export function escapeHtml(value) {
  return String(value ?? '').replace(/[&<>"]/g, (ch) => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;' }[ch]));
}

export function brandedReportShell({ title, body, subtitle = 'گزارش رسمی سیستم' }) {
  const safeTitle = escapeHtml(title);
  const css = `
    @page{size:A4;margin:12mm}
    *{box-sizing:border-box}
    body{margin:0;background:#f3f5f6;color:#1b2126;direction:rtl;font-family:Vazirmatn,Tahoma,Arial,sans-serif;padding:22px}
    .report{background:#fff;border-radius:18px;overflow:hidden;border:1px solid #e7eaec;box-shadow:0 8px 28px rgba(16,36,61,.10)}
    .brand-head{background:linear-gradient(135deg,#10243d,#1b365d);color:#fff;padding:18px 22px;display:flex;align-items:center;justify-content:space-between;gap:16px}
    .brand-title{display:flex;align-items:center;gap:12px}
    .brand-title img{width:58px;height:58px;object-fit:contain;border-radius:14px;background:#fff;padding:5px}
    .brand-title h1{margin:0;font-size:20px}
    .brand-title span{display:block;color:#f8d348;font-size:12px;margin-top:4px;font-weight:800}
    .report-date{color:#d8dee3;font-size:12px}
    .report-body{padding:20px}
    .report-body h1{margin:0 0 14px;color:#10243d;font-size:20px}
    .meta{display:grid;grid-template-columns:repeat(2,1fr);gap:10px;margin:16px 0}
    .meta div{border:1px solid #edf0f2;background:#f8fafb;border-radius:12px;padding:10px}
    table{width:100%;border-collapse:separate;border-spacing:0;margin-top:12px;overflow:hidden;border:1px solid #e7eaec;border-radius:14px}
    th{background:#10243d;color:#fff;font-weight:800}
    td,th{padding:10px;border-bottom:1px solid #edf0f2;text-align:right;font-size:12px}
    tr:nth-child(even) td{background:#fafafa}
    .money{direction:ltr}
    .footer{margin-top:42px;display:flex;justify-content:space-between;gap:16px}
    .footer span{flex:1;border-top:1px solid #ccd3da;padding-top:10px;text-align:center;color:#5b6670}
    .print-btn{margin:0 0 12px;background:#a8672e;color:#fff;border:0;border-radius:12px;padding:10px 14px;font-weight:800;cursor:pointer}
    @media print{body{background:#fff;padding:0}.print-btn{display:none}.report{box-shadow:none;border-radius:0}}
  `;
  return `<!doctype html><html dir="rtl" lang="fa"><head><meta charset="utf-8"><title>${safeTitle}</title><style>${css}</style></head><body><button class="print-btn" onclick="window.print()">چاپ / ذخیره PDF</button><main class="report"><header class="brand-head"><div class="brand-title"><img src="${ARYAMAN_LOGO_DATA_URI}" alt="Aryaman"><div><h1>${safeTitle}</h1><span>${ARYAMAN_BRAND_FA}</span></div></div><div class="report-date">${escapeHtml(subtitle)}</div></header><section class="report-body">${body}</section></main></body></html>`;
}

export function brandedTableHtml(title, headers, rows) {
  const table = `<table><thead><tr>${headers.map((h) => `<th>${escapeHtml(h)}</th>`).join('')}</tr></thead><tbody>${rows.map((r) => `<tr>${r.map((c) => `<td>${escapeHtml(c)}</td>`).join('')}</tr>`).join('')}</tbody></table>`;
  return brandedReportShell({ title, body: `<h1>${escapeHtml(title)}</h1>${table}` });
}

export function brandedExcelTableHtml(title, headers, rows, subtitle = 'خروجی اکسل اتوماسیون') {
  const safeTitle = escapeHtml(title);
  const headerStyle = 'background:#10243d;color:#ffffff;font-weight:700;border:1px solid #10243d;padding:8px;text-align:right;';
  const cellStyle = 'border:1px solid #d8dee3;padding:7px;text-align:right;mso-number-format:\\@;';
  const metaStyle = 'border:1px solid #d8dee3;background:#f8fafb;padding:8px;text-align:right;font-weight:700;color:#10243d;';
  return `<!doctype html><html dir="rtl" lang="fa"><head><meta charset="utf-8"><style>body{font-family:Tahoma,Arial,sans-serif;direction:rtl}table{border-collapse:collapse;width:100%}.money{mso-number-format:\\@}</style></head><body>
    <table style="border-collapse:collapse;width:100%;direction:rtl">
      <tr>
        <td style="${metaStyle};width:88px"><img src="${ARYAMAN_LOGO_DATA_URI}" width="64" height="64" style="background:#fff;border:1px solid #d8dee3;padding:4px" alt="logo"></td>
        <td colspan="${Math.max(headers.length - 1, 1)}" style="${metaStyle};font-size:18px">${safeTitle}<br><span style="font-size:12px;color:#a8672e">${ARYAMAN_BRAND_FA} · ${escapeHtml(subtitle)}</span></td>
      </tr>
      <tr>${headers.map((h) => `<th style="${headerStyle}">${escapeHtml(h)}</th>`).join('')}</tr>
      ${rows.map((r, index) => { const rowBg = index % 2 === 1 ? 'background:#f7f7f7;' : 'background:#ffffff;'; return `<tr>${r.map((c) => `<td style="${cellStyle}${rowBg}">${escapeHtml(c)}</td>`).join('')}</tr>`; }).join('')}
    </table>
  </body></html>`;
}
